/* The VM's generated byte lock: register/flag effects, contention and guard. */
#include "../runtime/rt.h"
#include <assert.h>
#include <pthread.h>
#include <sched.h>
#include <setjmp.h>
#include <stdio.h>
#include <stdlib.h>

const struct rt_fn { uint32_t addr; GuestFn fn; } rt_fntab[]={{0,0}};
const unsigned rt_fntab_n=0;
const struct rt_imp { uint32_t iat; const char *name; } rt_imptab[]={{0,"unused"}};
const unsigned rt_imptab_n=0;
const struct rt_image { const char *name; uint32_t base, imp_first, imp_count; } rt_images[]={{"",0x400000,0,0}};
const unsigned rt_images_n=1;
extern __thread jmp_buf *fault_jmp;
extern GuestFn rt_lookup(uint32_t addr);
static const uint32_t entry=0x1b200c8, context=0x1b20000, lock_byte=0x1004;
static Ctx context_for_call(void)
{
    Ctx c={.eax=19,.ebx=context,.ecx=23,.edx=29,.esi=31,.ebp=37,.esp=0x8000};
    flags_set(&c.f,0x202,0xffffffffu);
    rt_w32(G_MEM,c.esp,0xdeadbeef);return c;
}
static void verify(Ctx *c, unsigned before)
{
    assert(c->eax==19 && c->ebx==context && c->ecx==23 && c->edx==29 && c->esi==31 && c->ebp==37);
    assert(c->edi==lock_byte && c->esp==0x8004 && c->tc==0);
    uint32_t f=flags_get(&c->f);
    assert(!(f&F_CF) && !!(f&F_ZF)==(before==1) && !(f&F_SF));
    assert(!!(f&F_OF)==(before==128));
}
static void *worker(void *arg) { rt_call(arg,entry); return 0; }
int main(void)
{
    G_MEM=calloc(1,0x2000000);assert(G_MEM);
    const uint8_t code[]={0x8b,0xbb,0x20,3,0,0,0x81,0xc7,4,0,0,0,0xf0,0xfe,0x0f,0x79,9,0x80,0x3f,0,0xf3,0x90,0x7e,0xf9,0xeb,0xf2,0xc3};
    memcpy(G_MEM+entry,code,sizeof code);rt_w32(G_MEM,context+0x320,lock_byte-4);
    const unsigned values[]={1,2,127,128};
    for(unsigned i=0;i<sizeof values/sizeof values[0];i++) {
        Ctx c=context_for_call();G_MEM[lock_byte]=values[i];rt_call(&c,entry);
        assert(G_MEM[lock_byte]==values[i]-1);verify(&c,values[i]);
    }
    rt_w32(G_MEM,entry+2,0x334);rt_w32(G_MEM,entry+8,8);rt_w32(G_MEM,context+0x334,lock_byte-8);
    Ctx alternate=context_for_call();G_MEM[lock_byte]=1;rt_call(&alternate,entry);verify(&alternate,1);
    memcpy(G_MEM+entry,code,sizeof code);
    Ctx c=context_for_call();G_MEM[lock_byte]=0;pthread_t thread;
    assert(!pthread_create(&thread,0,worker,&c));
    unsigned tries=1000000;
    while(__atomic_load_n(G_MEM+lock_byte,__ATOMIC_RELAXED)!=255) { assert(--tries);sched_yield(); }
    __atomic_store_n(G_MEM+lock_byte,1,__ATOMIC_SEQ_CST);
    assert(!pthread_join(thread,0));verify(&c,1);assert(G_MEM[lock_byte]==0);
    const uint8_t release[]={0x58,0x8b,0xbb,0x20,3,0,0,0x81,0xc7,4,0,0,0,0x8a,0x47,1,0x86,7,0x81,0xc3,0x24,0,0,0,0xc7,3,0,0,0,0,0x9d,0x61,0xc2,8,0};
    memcpy(G_MEM+entry,release,sizeof release);
    for(unsigned variant=0;variant<2;variant++) {
        uint32_t slot=0x320+variant*4, offset=4+variant, cleared=0x24+variant*4;
        rt_w32(G_MEM,entry+3,slot);rt_w32(G_MEM,entry+9,offset);rt_w32(G_MEM,entry+20,cleared);
        rt_w32(G_MEM,context+slot,lock_byte-offset);rt_w32(G_MEM,context+cleared,0x12345678);
        c=context_for_call();G_MEM[lock_byte]=255;G_MEM[lock_byte+1]=1;
        rt_w32(G_MEM,0x8004,0xed7);
        for(unsigned i=0;i<8;i++) rt_w32(G_MEM,0x8008+4*i,100+i);
        rt_w32(G_MEM,0x8028,0x12345678);
        rt_lookup(entry)(&c);
        assert(G_MEM[lock_byte]==1 && rt_r32(G_MEM,context+cleared)==0);
        assert(c.edi==100 && c.esi==101 && c.ebp==102 && c.ebx==104);
        assert(c.edx==105 && c.ecx==106 && c.eax==107 && c.esp==0x8034 && c.tc==0x12345678);
        assert((flags_get(&c.f)&0xcd5u)==(0xed7u&0xcd5u) && c.f.df);
    }
    G_MEM[entry]=0x90; c=context_for_call();jmp_buf jump;fault_jmp=&jump;
    if(!setjmp(jump)) { rt_call(&c,entry);assert(!"changed code was accepted"); }
    fault_jmp=0;free(G_MEM);puts("BW generated locks: acquire/release, registers, flags, contention and code guard passed");
}
